namespace sv_192c75ff065949c0b006c6adfb0e93de.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service (one per circuit) that holds theme state and notifies subscribers on change.
/// </summary>
public class ThemeService
{
    public ThemeMode Theme { get; private set; } = ThemeMode.System;
    public string AccentColor { get; private set; } = "#0d6efd";

    public event Action? OnChange;

    public void SetTheme(ThemeMode theme)
    {
        if (Theme == theme) return;
        Theme = theme;
        OnChange?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        if (AccentColor == color) return;
        AccentColor = color;
        OnChange?.Invoke();
    }

    public void SetAll(ThemeMode theme, string accentColor)
    {
        Theme = theme;
        AccentColor = accentColor;
        OnChange?.Invoke();
    }
}

@rendermode InteractiveServer
@implements IDisposable
@inject Services.ThemeService ThemeService

<span class="badge" style="background-color: @ThemeService.AccentColor; color: white;">
    @ThemeService.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@rendermode InteractiveServer
@implements IDisposable
@inject Services.ThemeService ThemeService

<button class="btn btn-sm btn-outline-secondary" @onclick="CycleTheme" title="Toggle theme">
    @GetIcon()
</button>

@code {
    private string GetIcon() => ThemeService.Theme switch
    {
        Services.ThemeMode.Light => "☀️",
        Services.ThemeMode.Dark => "🌙",
        _ => "💻"
    };

    private void CycleTheme()
    {
        var next = ThemeService.Theme switch
        {
            Services.ThemeMode.Light => Services.ThemeMode.Dark,
            Services.ThemeMode.Dark => Services.ThemeMode.System,
            _ => Services.ThemeMode.Light
        };
        ThemeService.SetTheme(next);
    }

    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject Services.ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="mb-3">
    <label class="form-label">Theme</label>
    <select class="form-select" style="max-width: 200px;" @bind="selectedTheme">
        @foreach (var mode in Enum.GetValues<Services.ThemeMode>())
        {
            <option value="@mode">@mode</option>
        }
    </select>
</div>

<div class="mb-3">
    <label class="form-label">Accent Color</label>
    <input type="color" class="form-control form-control-color" @bind="selectedColor" />
</div>

<button class="btn btn-primary" @onclick="Save">Save Preferences</button>

<p class="mt-3 text-muted">
    Current: <strong>@ThemeService.Theme</strong> / <span style="color: @ThemeService.AccentColor;">@ThemeService.AccentColor</span>
</p>

@code {
    private Services.ThemeMode selectedTheme;
    private string selectedColor = "#0d6efd";

    protected override void OnInitialized()
    {
        selectedTheme = ThemeService.Theme;
        selectedColor = ThemeService.AccentColor;
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void Save()
    {
        ThemeService.SetAll(selectedTheme, selectedColor);
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(() =>
        {
            selectedTheme = ThemeService.Theme;
            selectedColor = ThemeService.AccentColor;
            StateHasChanged();
        });
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

